#!/usr/bin/env node
/**
 * Builds src/lib/permits-list.generated.ts from the site's Notion cache
 * (../Sito_Nuovo/_cache/permits-it.json): slug, title, emoji, category and
 * whether the permit has a renewal checklist. Used by the PRO scadenziario
 * (permit picker + link to the renewal checklist on sospermesso.it).
 *
 *   node scripts/generate-permits-list.js
 *
 * Same pattern as generate-pro-content.js: the generated file is committed.
 */
const fs = require('fs');
const path = require('path');

const SRC = path.join(__dirname, '..', '..', 'Sito_Nuovo', '_cache', 'permits-it.json');
const DEST = path.join(__dirname, '..', 'src', 'lib', 'permits-list.generated.ts');

const permits = JSON.parse(fs.readFileSync(SRC, 'utf-8'))
  .filter((p) => p.slug && p.tipo && !p.isPlaceholder)
  .map((p) => ({
    slug: p.slug,
    titolo: p.tipo,
    emoji: p.emoji || '',
    categoria: p.categoria || null,
    rinnovo: Array.isArray(p.rinnovoDocuments) && p.rinnovoDocuments.length > 0,
  }))
  .sort((a, b) => a.titolo.localeCompare(b.titolo, 'it'));

const out = `/**
 * AUTO-GENERATED by scripts/generate-permits-list.js — DO NOT EDIT.
 * Source: Sito_Nuovo/_cache/permits-it.json (${permits.length} permits).
 */

/* eslint-disable */
export interface PermitListItem {
  slug: string;
  titolo: string;
  emoji: string;
  categoria: string | null;
  /** True when sospermesso.it has a renewal checklist (#rinnovo). */
  rinnovo: boolean;
}

export const permitsList: readonly PermitListItem[] = ${JSON.stringify(permits, null, 2)};

export const permitsBySlug: Record<string, PermitListItem> = Object.fromEntries(
  permitsList.map((p) => [p.slug, p]),
);
`;
fs.writeFileSync(DEST, out);
console.log(`[generate-permits-list] ${permits.length} permits → ${path.relative(process.cwd(), DEST)}`);
